const SEO: Record<Exclude<Locale, "en">, SeoDict> = {
  es: { metaHeading: "\u00bfQu\u00e9 es un test de mecanograf\u00eda gratis?", introA: "Un <strong>test de mecanograf\u00eda gratis</strong> mide en segundos tu velocidad de escritura y tu precisi\u00f3n al teclear un texto durante un tiempo determinado. Test de mecanograf\u00eda Cabra calcula tu WPM (palabras por minuto), tu precisi\u00f3n y tus errores al finalizar cada intento.", introB: "Puedes practicar sin crear una cuenta: elige dificultad y duraci\u00f3n, escribe el texto mostrado y consulta tus resultados al instante. Es una forma r\u00e1pida y honesta de medir tu velocidad de escritura online.", howHeading: "C\u00f3mo funciona el test de mecanograf\u00eda online y qui\u00e9n puede usarlo", howA: "Elige entre las dificultades F\u00e1cil, Medio o Dif\u00edcil y selecciona una duraci\u00f3n de 1, 2, 3 o 5 minutos. El cron\u00f3metro se activa autom\u00e1ticamente en cuanto empiezas a escribir, y el indicador de posici\u00f3n te muestra siempre d\u00f3nde est\u00e1s en el texto.", howB: "Este test de mecanograf\u00eda es \u00fatil para estudiantes, profesionales, principiantes y cualquier persona que quiera medir o mejorar su velocidad de escritura en teclado. Puedes repetir la prueba tantas veces como quieras para trabajar tu precisi\u00f3n antes de aumentar la velocidad. Tambi\u00e9n puedes usar el modo personalizado para practicar con tu propio texto, ideal para una pr\u00e1ctica de texto m\u00e1s espec\u00edfica.", chartHeading: "Tabla de velocidad de mecanograf\u00eda", chartIntro: "El WPM es un buen punto de referencia, pero conviene interpretarlo junto con la precisi\u00f3n y las condiciones de la prueba. Compara tus propios resultados en condiciones similares para ver tu progreso real.", tableLevel: "Nivel", tableWpm: "WPM", tableMeaning: "Qu\u00e9 significa", tableNext: "Siguiente objetivo" },
  de: { metaHeading: "Was ist ein kostenloser Schreibtest?", introA: "Ein <strong>kostenloser Schreibtest</strong> misst in Sekunden, wie schnell und genau du einen angezeigten Text auf der Tastatur eingibst. Schreibtest Ziege berechnet nach jedem Versuch deine WPM (W\u00f6rter pro Minute), deine Genauigkeit und deine Fehler.", introB: "Du kannst ohne Konto \u00fcben: W\u00e4hle Schwierigkeit und Dauer, tippe den angezeigten Text und sieh deine Ergebnisse sofort. Es ist eine schnelle und ehrliche Art, deine Tippgeschwindigkeit online zu messen.", howHeading: "So funktioniert der Online-Schreibtest und wer ihn nutzen kann", howA: "W\u00e4hle zwischen Leicht, Mittel oder Schwer und w\u00e4hle eine Dauer von 1, 2, 3 oder 5 Minuten. Der Timer startet automatisch, sobald du zu tippen beginnst, und der Cursor zeigt dir immer deine aktuelle Position im Text.", howB: "Dieser Schreibtest ist n\u00fctzlich f\u00fcr Sch\u00fcler, Berufst\u00e4tige, Anf\u00e4nger und alle, die ihre Tippgeschwindigkeit messen oder verbessern m\u00f6chten. Du kannst den Test beliebig oft wiederholen, um zuerst deine Genauigkeit zu verbessern, bevor du die Geschwindigkeit steigerst. Du kannst au\u00dferdem den benutzerdefinierten Modus nutzen, um mit deinem eigenen Text zu \u00fcben \u2013 ideal f\u00fcr gezieltes Text-Training.", chartHeading: "Tippgeschwindigkeits-Tabelle", chartIntro: "WPM ist ein guter Richtwert, sollte aber zusammen mit Genauigkeit und Testbedingungen betrachtet werden. Vergleiche deine eigenen Ergebnisse unter \u00e4hnlichen Bedingungen, um echten Fortschritt zu sehen.", tableLevel: "Stufe", tableWpm: "WPM", tableMeaning: "Bedeutung", tableNext: "N\u00e4chstes Ziel" },
  fr: { metaHeading: "Qu'est-ce qu'un test de frappe gratuit ?", introA: "Un <strong>test de frappe gratuit</strong> mesure en quelques secondes votre vitesse de frappe et votre pr\u00e9cision en tapant un texte affich\u00e9 pendant une dur\u00e9e d\u00e9termin\u00e9e. Test de frappe Ch\u00e8vre calcule votre WPM (mots par minute), votre pr\u00e9cision et vos erreurs \u00e0 la fin de chaque essai.", introB: "Vous pouvez vous entra\u00eener sans cr\u00e9er de compte : choisissez la difficult\u00e9 et la dur\u00e9e, tapez le texte affich\u00e9 et consultez vos r\u00e9sultats instantan\u00e9ment. C'est une fa\u00e7on rapide et honn\u00eate de mesurer votre vitesse de frappe en ligne.", howHeading: "Comment fonctionne le test de frappe en ligne et qui peut l'utiliser", howA: "Choisissez entre Facile, Moyen ou Difficile, puis s\u00e9lectionnez une dur\u00e9e de 1, 2, 3 ou 5 minutes. Le chronom\u00e8tre d\u00e9marre automatiquement d\u00e8s que vous commencez \u00e0 taper, et le curseur indique toujours votre position actuelle dans le texte.", howB: "Ce test de frappe est utile pour les \u00e9tudiants, les professionnels, les d\u00e9butants et toute personne souhaitant mesurer ou am\u00e9liorer sa vitesse de frappe au clavier. Vous pouvez r\u00e9p\u00e9ter le test autant de fois que vous le souhaitez pour travailler votre pr\u00e9cision avant d'augmenter votre vitesse. Vous pouvez aussi utiliser le mode personnalis\u00e9 pour taper votre propre texte, id\u00e9al pour un entrainement textuel cibl\u00e9.", chartHeading: "Tableau des vitesses de frappe", chartIntro: "Le WPM est une bonne r\u00e9f\u00e9rence, mais il doit \u00eatre interpr\u00e9t\u00e9 avec la pr\u00e9cision et les conditions du test. Comparez vos propres r\u00e9sultats dans des conditions similaires pour voir vos progr\u00e8s r\u00e9els.", tableLevel: "Niveau", tableWpm: "WPM", tableMeaning: "Signification", tableNext: "Objectif suivant" },
  it: { metaHeading: "Cos'\u00e8 un test di digitazione gratuito?", introA: "Un <strong>test di digitazione gratuito</strong> misura in pochi secondi la tua velocit\u00e0 e precisione digitando un testo visualizzato per un tempo stabilito. Test di Digitazione Capra calcola il tuo WPM (parole al minuto), la precisione e gli errori al termine di ogni tentativo.", introB: "Puoi allenarti senza creare un account: scegli difficolt\u00e0 e durata, digita il testo mostrato e visualizza subito i tuoi risultati. \u00c8 un modo rapido e onesto per misurare la tua velocit\u00e0 di digitazione online.", howHeading: "Come funziona il test di digitazione online e chi pu\u00f2 usarlo", howA: "Scegli tra Facile, Medio o Difficile e seleziona una durata di 1, 2, 3 o 5 minuti. Il timer si avvia automaticamente non appena inizi a digitare, e il cursore mostra sempre la tua posizione attuale nel testo.", howB: "Questo test di digitazione \u00e8 utile per studenti, professionisti, principianti e chiunque voglia misurare o migliorare la propria velocit\u00e0 di digitazione. Puoi ripetere il test tutte le volte che vuoi per lavorare sulla precisione prima di aumentare la velocit\u00e0. Puoi anche usare la modalit\u00e0 personalizzata per digitare un testo a tua scelta, ideale per un'esercitazione di testo mirata.", chartHeading: "Tabella delle velocit\u00e0 di digitazione", chartIntro: "Il WPM \u00e8 un buon punto di riferimento, ma va interpretato insieme alla precisione e alle condizioni del test. Confronta i tuoi risultati in condizioni simili per vedere i tuoi progressi reali.", tableLevel: "Livello", tableWpm: "WPM", tableMeaning: "Significato", tableNext: "Prossimo obiettivo" },
  pt: { metaHeading: "O que \u00e9 um teste de digita\u00e7\u00e3o gratuito?", introA: "Um <strong>teste de digita\u00e7\u00e3o gratuito</strong> mede em segundos sua velocidade e precis\u00e3o ao digitar um texto exibido durante um tempo definido. O Teste de Digita\u00e7\u00e3o Cabra calcula seu WPM (palavras por minuto), precis\u00e3o e erros ao final de cada tentativa.", introB: "Voc\u00ea pode praticar sem criar uma conta: escolha dificuldade e dura\u00e7\u00e3o, digite o texto exibido e veja seus resultados instantaneamente. \u00c9 uma forma r\u00e1pida e honesta de medir sua velocidade de digita\u00e7\u00e3o online.", howHeading: "Como funciona o teste de digita\u00e7\u00e3o online e quem pode us\u00e1-lo", howA: "Escolha entre F\u00e1cil, M\u00e9dio ou Dif\u00edcil e selecione uma dura\u00e7\u00e3o de 1, 2, 3 ou 5 minutos. O cron\u00f4metro come\u00e7a automaticamente assim que voc\u00ea come\u00e7a a digitar, e o cursor sempre mostra sua posi\u00e7\u00e3o atual no texto.", howB: "Este teste de digita\u00e7\u00e3o \u00e9 \u00fatil para estudantes, profissionais, principiantes e qualquer pessoa que queira medir ou melhorar sua velocidade de digita\u00e7\u00e3o. Voc\u00ea pode repetir o teste quantas vezes quiser para trabalhar sua precis\u00e3o antes de aumentar a velocidade. Voc\u00ea tamb\u00e9m pode usar o modo personalizado para digitar seu pr\u00f3prio texto, ideal para uma pr\u00e1tica de texto mais espec\u00edfica.", chartHeading: "Tabela de velocidade de digita\u00e7\u00e3o", chartIntro: "O WPM \u00e9 uma boa refer\u00eancia, mas deve ser interpretado junto com a precis\u00e3o e as condi\u00e7\u00f5es do teste. Compare seus pr\u00f3prios resultados em condi\u00e7\u00f5es semelhantes para ver seu progresso real.", tableLevel: "N\u00edvel", tableWpm: "WPM", tableMeaning: "O que significa", tableNext: "Pr\u00f3xima meta" },
  pl: { metaHeading: "Co to jest darmowy test pisania?", introA: "<strong>Darmowy test pisania</strong> w kilka sekund mierzy Twoj\u0105 szybko\u015b\u0107 i dok\u0142adno\u015b\u0107 podczas pisania wy\u015bwietlonego tekstu w okre\u015blonym czasie. Test Pisania Koza obliczy Tw\u00f3j WPM (s\u0142owa na minut\u0119), dok\u0142adno\u015b\u0107 i b\u0142\u0119dy po ka\u017cdej pr\u00f3bie.", introB: "Mo\u017cesz trenowa\u0107 bez konta: wybierz trudno\u015b\u0107 i czas trwania, wpisz wy\u015bwietlony tekst i zobacz wyniki natychmiast. To szybki i uczciwy spos\u00f3b na sprawdzenie swojej szybko\u015bci pisania online.", howHeading: "Jak dzia\u0142a test pisania online i kto mo\u017ce go u\u017cywa\u0107", howA: "Wybierz \u0141atwy, \u015aredni lub Trudny poziom, a nast\u0119pnie czas trwania 1, 2, 3 lub 5 minut. Stoper uruchamia si\u0119 automatycznie, gdy zaczynasz pisa\u0107, a kursor zawsze wskazuje Twoj\u0105 aktualn\u0105 pozycj\u0119 w tek\u015bcie.", howB: "Ten test pisania jest przydatny dla uczni\u00f3w, profesjonalist\u00f3w, pocz\u0105tkuj\u0105cych i ka\u017cdego, kto chce zmierzy\u0107 lub poprawi\u0107 swoj\u0105 szybko\u015b\u0107 pisania. Mo\u017cesz powtarza\u0107 test tak cz\u0119sto, jak chcesz, aby najpierw popracowa\u0107 nad dok\u0142adno\u015bci\u0105, a potem zwi\u0119ksza\u0107 szybko\u015b\u0107. Mo\u017cesz te\u017c skorzysta\u0107 z trybu niestandardowego, aby pisa\u0107 w\u0142asny tekst \u2014 to \u015bwietna praktyka tekstu dopasowana do Twoich potrzeb.", chartHeading: "Tabela szybko\u015bci pisania", chartIntro: "WPM to dobry punkt odniesienia, ale nale\u017cy go interpretowa\u0107 wraz z dok\u0142adno\u015bci\u0105 i warunkami testu. Por\u00f3wnuj w\u0142asne wyniki w podobnych warunkach, aby zobaczy\u0107 realne post\u0119py.", tableLevel: "Poziom", tableWpm: "WPM", tableMeaning: "Co to znaczy", tableNext: "Nast\u0119pny cel" },
  tr: { metaHeading: "\u00dccretsiz yazma testi nedir?", introA: "<strong>\u00dccretsiz yazma testi</strong>, belirli bir s\u00fcre i\u00e7inde g\u00f6sterilen bir metni yazarken h\u0131z\u0131n\u0131 ve do\u011frulu\u011funu saniyeler i\u00e7inde \u00f6l\u00e7er. Yazma Testi Ke\u00e7i, her denemenin sonunda WPM'ini (dakikadaki kelime say\u0131s\u0131), do\u011frulu\u011funu ve hatalar\u0131n\u0131 hesaplar.", introB: "Hesap olu\u015fturmadan pratik yapabilirsin: zorluk ve s\u00fcre se\u00e7, g\u00f6sterilen metni yaz ve sonu\u00e7lar\u0131n\u0131 an\u0131nda g\u00f6r. \u00c7evrimi\u00e7i yazma h\u0131z\u0131n\u0131 \u00f6l\u00e7menin h\u0131zl\u0131 ve d\u00fcr\u00fcst bir yoludur.", howHeading: "\u00c7evrimi\u00e7i yazma testi nas\u0131l \u00e7al\u0131\u015f\u0131r ve kimler kullanabilir", howA: "Kolay, Orta veya Zor aras\u0131ndan se\u00e7, ard\u0131ndan 1, 2, 3 veya 5 dakikal\u0131k bir s\u00fcre belirle. Yazmaya ba\u015flad\u0131\u011f\u0131n anda zamanlay\u0131c\u0131 otomatik olarak ba\u015flar ve imle\u00e7 her zaman metindeki mevcut konumunu g\u00f6sterir.", howB: "Bu yazma testi \u00f6\u011frenciler, profesyoneller, yeni ba\u015flayanlar ve yazma h\u0131z\u0131n\u0131 \u00f6l\u00e7mek veya geli\u015ftirmek isteyen herkes i\u00e7in kullan\u0131\u015fl\u0131d\u0131r. H\u0131z\u0131n\u0131 art\u0131rmadan \u00f6nce do\u011frulu\u011fun \u00fczerinde \u00e7al\u0131\u015fmak i\u00e7in testi istedi\u011fin kadar tekrarlayabilirsin. Kendi metnini yazmak i\u00e7in \u00f6zel modu da kullanabilirsin; bu, hedefe y\u00f6nelik bir metin prati\u011fi i\u00e7in idealdir.", chartHeading: "Yazma h\u0131z\u0131 tablosu", chartIntro: "WPM iyi bir referans noktas\u0131d\u0131r, ancak do\u011fruluk ve test ko\u015fullar\u0131yla birlikte de\u011ferlendirilmelidir. Ger\u00e7ek ilerlemeni g\u00f6rmek i\u00e7in kendi sonu\u00e7lar\u0131n\u0131 benzer ko\u015fullarda kar\u015f\u0131la\u015ft\u0131r.", tableLevel: "Seviye", tableWpm: "WPM", tableMeaning: "Ne anlama gelir", tableNext: "Sonraki hedef" },
  uk: { metaHeading: "\u0429\u043e \u0442\u0430\u043a\u0435 \u0431\u0435\u0437\u043a\u043e\u0448\u0442\u043e\u0432\u043d\u0438\u0439 \u0442\u0435\u0441\u0442 \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443?", introA: "<strong>\u0411\u0435\u0437\u043a\u043e\u0448\u0442\u043e\u0432\u043d\u0438\u0439 \u0442\u0435\u0441\u0442 \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443</strong> \u0437\u0430 \u043a\u0456\u043b\u044c\u043a\u0430 \u0441\u0435\u043a\u0443\u043d\u0434 \u0432\u0438\u043c\u0456\u0440\u044e\u0454 \u0432\u0430\u0448\u0443 \u0448\u0432\u0438\u0434\u043a\u0456\u0441\u0442\u044c \u0456 \u0442\u043e\u0447\u043d\u0456\u0441\u0442\u044c \u043f\u0456\u0434 \u0447\u0430\u0441 \u0432\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0443 \u0437\u0430 \u0432\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u0447\u0430\u0441. \u0422\u0435\u0441\u0442 \u0434\u0440\u0443\u043a\u0443 \u041a\u043e\u0437\u0430 \u0440\u043e\u0437\u0440\u0430\u0445\u043e\u0432\u0443\u0454 \u0432\u0430\u0448 WPM (\u0441\u043b\u0456\u0432 \u0437\u0430 \u0445\u0432\u0438\u043b\u0438\u043d\u0443), \u0442\u043e\u0447\u043d\u0456\u0441\u0442\u044c \u0456 \u043f\u043e\u043c\u0438\u043b\u043a\u0438 \u043f\u0456\u0441\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0457 \u0441\u043f\u0440\u043e\u0431\u0438.", introB: "\u0412\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0442\u0440\u0435\u043d\u0443\u0432\u0430\u0442\u0438\u0441\u044f \u0431\u0435\u0437 \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443: \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u043a\u043b\u0430\u0434\u043d\u0456\u0441\u0442\u044c \u0456 \u0442\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c, \u0432\u0432\u0435\u0434\u0456\u0442\u044c \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u0438\u0439 \u0442\u0435\u043a\u0441\u0442 \u0456 \u043e\u0434\u0440\u0430\u0437\u0443 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438. \u0426\u0435 \u0448\u0432\u0438\u0434\u043a\u0438\u0439 \u0456 \u0447\u0435\u0441\u043d\u0438\u0439 \u0441\u043f\u043e\u0441\u0456\u0431 \u0432\u0438\u043c\u0456\u0440\u044f\u0442\u0438 \u0448\u0432\u0438\u0434\u043a\u0456\u0441\u0442\u044c \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443 \u043e\u043d\u043b\u0430\u0439\u043d.", howHeading: "\u042f\u043a \u043f\u0440\u0430\u0446\u044e\u0454 \u043e\u043d\u043b\u0430\u0439\u043d-\u0442\u0435\u0441\u0442 \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443 \u0456 \u0445\u0442\u043e \u043c\u043e\u0436\u0435 \u043d\u0438\u043c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0442\u0438\u0441\u044f", howA: "\u0412\u0438\u0431\u0435\u0440\u0456\u0442\u044c \u041b\u0435\u0433\u043a\u0438\u0439, \u0421\u0435\u0440\u0435\u0434\u043d\u0456\u0439 \u0430\u0431\u043e \u0421\u043a\u043b\u0430\u0434\u043d\u0438\u0439 \u0440\u0456\u0432\u0435\u043d\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0442\u0440\u0438\u0432\u0430\u043b\u0456\u0441\u0442\u044c 1, 2, 3 \u0430\u0431\u043e 5 \u0445\u0432\u0438\u043b\u0438\u043d. \u0422\u0430\u0439\u043c\u0435\u0440 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f, \u0449\u043e\u0439\u043d\u043e \u0432\u0438 \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u0435 \u0432\u0432\u043e\u0434\u0438\u0442\u0438 \u0442\u0435\u043a\u0441\u0442, \u0430 \u043a\u0443\u0440\u0441\u043e\u0440 \u0437\u0430\u0432\u0436\u0434\u0438 \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u0432\u0430\u0448\u0443 \u043f\u043e\u0442\u043e\u0447\u043d\u0443 \u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0432 \u0442\u0435\u043a\u0441\u0442\u0456.", howB: "\u0426\u0435\u0439 \u0442\u0435\u0441\u0442 \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443 \u043a\u043e\u0440\u0438\u0441\u043d\u0438\u0439 \u0434\u043b\u044f \u0441\u0442\u0443\u0434\u0435\u043d\u0442\u0456\u0432, \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u043e\u043d\u0430\u043b\u0456\u0432, \u043f\u043e\u0447\u0430\u0442\u043a\u0456\u0432\u0446\u0456\u0432 \u0456 \u0431\u0443\u0434\u044c-\u043a\u043e\u0433\u043e, \u0445\u0442\u043e \u0445\u043e\u0447\u0435 \u0432\u0438\u043c\u0456\u0440\u044f\u0442\u0438 \u0430\u0431\u043e \u043f\u043e\u043a\u0440\u0430\u0449\u0438\u0442\u0438 \u0448\u0432\u0438\u0434\u043a\u0456\u0441\u0442\u044c \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443. \u0412\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0442\u0435\u0441\u0442 \u0441\u0442\u0456\u043b\u044c\u043a\u0438 \u0440\u0430\u0437\u0456\u0432, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0445\u043e\u0447\u0435\u0442\u0435, \u0449\u043e\u0431 \u0441\u043f\u043e\u0447\u0430\u0442\u043a\u0443 \u043f\u043e\u043f\u0440\u0430\u0446\u044e\u0432\u0430\u0442\u0438 \u043d\u0430\u0434 \u0442\u043e\u0447\u043d\u0456\u0441\u0442\u044e, \u0430 \u043f\u043e\u0442\u0456\u043c \u0437\u0431\u0456\u043b\u044c\u0448\u0443\u0432\u0430\u0442\u0438 \u0448\u0432\u0438\u0434\u043a\u0456\u0441\u0442\u044c. \u0412\u0438 \u0442\u0430\u043a\u043e\u0436 \u043c\u043e\u0436\u0435\u0442\u0435 \u0441\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u0442\u0438\u0441\u044f \u0432\u043b\u0430\u0441\u043d\u0438\u043c \u0440\u0435\u0436\u0438\u043c\u043e\u043c, \u0449\u043e\u0431 \u0434\u0440\u0443\u043a\u0443\u0432\u0430\u0442\u0438 \u0441\u0432\u0456\u0439 \u0442\u0435\u043a\u0441\u0442 \u2014 \u0446\u0435 \u0447\u0443\u0434\u043e\u0432\u0430 \u0442\u0435\u043a\u0441\u0442\u043e\u0432\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u043f\u0456\u0434 \u0432\u0430\u0448\u0456 \u043f\u043e\u0442\u0440\u0435\u0431\u0438.", chartHeading: "\u0422\u0430\u0431\u043b\u0438\u0446\u044f \u0448\u0432\u0438\u0434\u043a\u043e\u0441\u0442\u0456 \u043d\u0430\u0431\u043e\u0440\u0443 \u0442\u0435\u043a\u0441\u0442\u0443", chartIntro: "WPM \u2014 \u0445\u043e\u0440\u043e\u0448\u0438\u0439 \u043e\u0440\u0456\u0454\u043d\u0442\u0438\u0440, \u0430\u043b\u0435 \u0439\u043e\u0433\u043e \u0432\u0430\u0440\u0442\u043e \u0440\u043e\u0437\u0433\u043b\u044f\u0434\u0430\u0442\u0438 \u0440\u0430\u0437\u043e\u043c \u0456\u0437 \u0442\u043e\u0447\u043d\u0456\u0441\u0442\u044e \u0442\u0430 \u0443\u043c\u043e\u0432\u0430\u043c\u0438 \u0442\u0435\u0441\u0442\u0443. \u041f\u043e\u0440\u0456\u0432\u043d\u044e\u0439\u0442\u0435 \u0432\u043b\u0430\u0441\u043d\u0456 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438 \u0437\u0430 \u043f\u043e\u0434\u0456\u0431\u043d\u0438\u0445 \u0443\u043c\u043e\u0432, \u0449\u043e\u0431 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0438 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0441.", tableLevel: "\u0420\u0456\u0432\u0435\u043d\u044c", tableWpm: "WPM", tableMeaning: "\u0429\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0454", tableNext: "\u041d\u0430\u0441\u0442\u0443\u043f\u043d\u0430 \u0446\u0456\u043b\u044c" },
  id: { metaHeading: "Apa itu tes mengetik gratis?", introA: "<strong>Tes mengetik gratis</strong> mengukur dalam hitungan detik seberapa cepat dan akurat kamu mengetik teks yang ditampilkan dalam waktu tertentu. Tes Mengetik Kambing menghitung WPM (kata per menit), akurasi, dan kesalahanmu setelah setiap percobaan.", introB: "Kamu bisa berlatih tanpa membuat akun: pilih tingkat kesulitan dan durasi, ketik teks yang ditampilkan, dan lihat hasilmu secara instan. Ini adalah cara cepat dan jujur untuk mengukur kecepatan mengetikmu secara online.", howHeading: "Cara kerja tes mengetik online dan siapa yang bisa menggunakannya", howA: "Pilih Mudah, Sedang, atau Sulit, lalu pilih durasi 1, 2, 3, atau 5 menit. Timer dimulai otomatis begitu kamu mulai mengetik, dan kursor selalu menunjukkan posisimu saat ini dalam teks.", howB: "Tes mengetik ini bermanfaat untuk siswa, profesional, pemula, dan siapa pun yang ingin mengukur atau meningkatkan kecepatan mengetiknya. Kamu bisa mengulang tes sesering yang kamu inginkan untuk melatih akurasi sebelum meningkatkan kecepatan. Kamu juga bisa menggunakan mode kustom untuk mengetik teks milikmu sendiri, cocok untuk teks latihan yang lebih spesifik.", chartHeading: "Tabel kecepatan mengetik", chartIntro: "WPM adalah acuan yang baik, tetapi sebaiknya ditafsirkan bersama akurasi dan kondisi tes. Bandingkan hasilmu sendiri dalam kondisi serupa untuk melihat kemajuan nyata.", tableLevel: "Tingkat", tableWpm: "WPM", tableMeaning: "Artinya", tableNext: "Target berikutnya" },
  zh: { metaHeading: "\u4ec0\u4e48\u662f\u514d\u8d39\u6253\u5b57\u6d4b\u8bd5\uff1f", introA: "<strong>\u514d\u8d39\u6253\u5b57\u6d4b\u8bd5</strong>\u80fd\u5728\u51e0\u79d2\u949f\u5185\u8861\u91cf\u4f60\u5728\u89c4\u5b9a\u65f6\u95f4\u5185\u8f93\u5165\u663e\u793a\u6587\u672c\u7684\u901f\u5ea6\u548c\u51c6\u786e\u5ea6\u3002\u6253\u5b57\u6d4b\u8bd5\u5c71\u7f8a\u4f1a\u5728\u6bcf\u6b21\u5c1d\u8bd5\u7ed3\u675f\u540e\u8ba1\u7b97\u4f60\u7684WPM\uff08\u6bcf\u5206\u949f\u5b57\u6570\uff09\u3001\u51c6\u786e\u7387\u548c\u9519\u8bef\u6570\u3002", introB: "\u4f60\u53ef\u4ee5\u65e0\u9700\u6ce8\u518c\u8d26\u6237\u5373\u53ef\u7ec3\u4e60\uff1a\u9009\u62e9\u96be\u5ea6\u548c\u65f6\u957f\uff0c\u8f93\u5165\u663e\u793a\u7684\u6587\u672c\uff0c\u5373\u53ef\u7acb\u5373\u67e5\u770b\u7ed3\u679c\u3002\u8fd9\u662f\u4e00\u79cd\u5feb\u901f\u3001\u771f\u5b9e\u5730\u8861\u91cf\u5728\u7ebf\u6253\u5b57\u901f\u5ea6\u7684\u65b9\u5f0f\u3002", howHeading: "\u5728\u7ebf\u6253\u5b57\u6d4b\u8bd5\u7684\u5de5\u4f5c\u539f\u7406\u4ee5\u53ca\u9002\u7528\u4eba\u7fa4", howA: "\u9009\u62e9\u7b80\u5355\u3001\u4e2d\u7b49\u6216\u56f0\u96be\u96be\u5ea6\uff0c\u7136\u540e\u9009\u62e91\u30012\u30013\u62165\u5206\u949f\u7684\u65f6\u957f\u3002\u5f53\u4f60\u5f00\u59cb\u8f93\u5165\u65f6\uff0c\u8ba1\u65f6\u5668\u4f1a\u81ea\u52a8\u542f\u52a8\uff0c\u5149\u6807\u4f1a\u4e00\u76f4\u663e\u793a\u4f60\u5728\u6587\u672c\u4e2d\u7684\u5f53\u524d\u4f4d\u7f6e\u3002", howB: "\u8fd9\u4e2a\u6253\u5b57\u6d4b\u8bd5\u5bf9\u5b66\u751f\u3001\u804c\u573a\u4eba\u58eb\u3001\u521d\u5b66\u8005\u4ee5\u53ca\u4efb\u4f55\u60f3\u8981\u8861\u91cf\u6216\u63d0\u5347\u6253\u5b57\u901f\u5ea6\u7684\u4eba\u90fd\u5f88\u6709\u7528\u3002\u4f60\u53ef\u4ee5\u968f\u610f\u91cd\u590d\u6d4b\u8bd5\uff0c\u5148\u63d0\u5347\u51c6\u786e\u7387\uff0c\u518d\u9010\u6b65\u63d0\u9ad8\u901f\u5ea6\u3002\u4f60\u8fd8\u53ef\u4ee5\u4f7f\u7528\u81ea\u5b9a\u4e49\u6a21\u5f0f\u8f93\u5165\u81ea\u5df1\u7684\u6587\u672c\uff0c\u8fdb\u884c\u66f4\u6709\u9488\u5bf9\u6027\u7684\u6587\u672c\u7ec3\u4e60\u3002", chartHeading: "\u6253\u5b57\u901f\u5ea6\u56fe\u8868", chartIntro: "WPM\u662f\u4e00\u4e2a\u5f88\u597d\u7684\u53c2\u8003\u6307\u6807\uff0c\u4f46\u5e94\u7ed3\u5408\u51c6\u786e\u7387\u548c\u6d4b\u8bd5\u6761\u4ef6\u6765\u89e3\u8bfb\u3002\u5728\u76f8\u4f3c\u6761\u4ef6\u4e0b\u6bd4\u8f83\u81ea\u5df1\u7684\u7ed3\u679c\uff0c\u80fd\u770b\u51fa\u771f\u6b63\u7684\u8fdb\u6b65\u3002", tableLevel: "\u7ea7\u522b", tableWpm: "WPM", tableMeaning: "\u542b\u4e49", tableNext: "\u4e0b\u4e00\u4e2a\u76ee\u6807" },
  ja: { metaHeading: "\u7121\u6599\u30bf\u30a4\u30d4\u30f3\u30b0\u30c6\u30b9\u30c8\u3068\u306f\uff1f", introA: "<strong>\u7121\u6599\u30bf\u30a4\u30d4\u30f3\u30b0\u30c6\u30b9\u30c8</strong>\u306f\u3001\u6c7a\u3081\u3089\u308c\u305f\u6642\u9593\u5185\u306b\u8868\u793a\u3055\u308c\u305f\u6587\u7ae0\u3092\u5165\u529b\u3059\u308b\u3053\u3068\u3067\u3001\u3042\u306a\u305f\u306e\u30bf\u30a4\u30d4\u30f3\u30b0\u901f\u5ea6\u3068\u6b63\u78ba\u3055\u3092\u6570\u79d2\u3067\u6e2c\u5b9a\u3057\u307e\u3059\u3002\u30bf\u30a4\u30d4\u30f3\u30b0\u30c6\u30b9\u30c8 \u30e4\u30ae\u306f\u3001\u5404\u8a66\u884c\u306e\u7d42\u4e86\u6642\u306bWPM\uff081\u5206\u3042\u305f\u308a\u306e\u5358\u8a9e\u6570\uff09\u3001\u6b63\u78ba\u7387\u3001\u30a8\u30e9\u30fc\u6570\u3092\u7b97\u51fa\u3057\u307e\u3059\u3002", introB: "\u30a2\u30ab\u30a6\u30f3\u30c8\u3092\u4f5c\u6210\u305b\u305a\u306b\u7df4\u7fd2\u3067\u304d\u307e\u3059\u3002\u96e3\u6613\u5ea6\u3068\u6642\u9593\u3092\u9078\u3073\u3001\u8868\u793a\u3055\u308c\u305f\u6587\u7ae0\u3092\u5165\u529b\u3059\u308c\u3070\u3001\u7d50\u679c\u306f\u3059\u3050\u306b\u8868\u793a\u3055\u308c\u307e\u3059\u3002\u30aa\u30f3\u30e9\u30a4\u30f3\u3067\u30bf\u30a4\u30d4\u30f3\u30b0\u901f\u5ea6\u3092\u6e2c\u308b\u3001\u624b\u8efd\u3067\u6b63\u78ba\u306a\u65b9\u6cd5\u3067\u3059\u3002", howHeading: "\u30aa\u30f3\u30e9\u30a4\u30f3\u30bf\u30a4\u30d4\u30f3\u30b0\u30c6\u30b9\u30c8\u306e\u4ed5\u7d44\u307f\u3068\u5bfe\u8c61\u8005", howA: "\u300c\u7c21\u5358\u300d\u300c\u666e\u901a\u300d\u300c\u96e3\u3057\u3044\u300d\u306e\u4e2d\u304b\u3089\u96e3\u6613\u5ea6\u3092\u9078\u3073\u30011\u5206\u30012\u5206\u30013\u5206\u30015\u5206\u306e\u4e2d\u304b\u3089\u6642\u9593\u3092\u9078\u3073\u307e\u3059\u3002\u6587\u5b57\u3092\u5165\u529b\u3057\u59cb\u3081\u308b\u3068\u540c\u6642\u306b\u30bf\u30a4\u30de\u30fc\u304c\u81ea\u52d5\u7684\u306b\u30b9\u30bf\u30fc\u30c8\u3057\u3001\u30ab\u30fc\u30bd\u30eb\u304c\u5e38\u306b\u6587\u7ae0\u5185\u306e\u73fe\u5728\u4f4d\u7f6e\u3092\u793a\u3057\u307e\u3059\u3002", howB: "\u3053\u306e\u30bf\u30a4\u30d4\u30f3\u30b0\u30c6\u30b9\u30c8\u306f\u3001\u5b66\u751f\u3001\u793e\u4f1a\u4eba\u3001\u521d\u5fc3\u8005\u3001\u305d\u3057\u3066\u30bf\u30a4\u30d4\u30f3\u30b0\u901f\u5ea6\u3092\u6e2c\u5b9a\u30fb\u5411\u4e0a\u3055\u305b\u305f\u3044\u3059\u3079\u3066\u306e\u4eba\u306b\u5f79\u7acb\u3061\u307e\u3059\u3002\u901f\u5ea6\u3092\u4e0a\u3052\u308b\u524d\u306b\u6b63\u78ba\u3055\u3092\u9ad8\u3081\u308b\u305f\u3081\u3001\u4f55\u5ea6\u3067\u3082\u30c6\u30b9\u30c8\u3092\u7e70\u308a\u8fd4\u3059\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002\u307e\u305f\u3001\u30ab\u30b9\u30bf\u30e0\u30e2\u30fc\u30c9\u3092\u4f7f\u3048\u3070\u81ea\u5206\u306e\u30c6\u30ad\u30b9\u30c8\u3092\u5165\u529b\u3067\u304d\u3001\u3088\u308a\u7684\u3092\u7d5e\u3063\u305f\u30c6\u30ad\u30b9\u30c8\u7df4\u7fd2\u304c\u3067\u304d\u307e\u3059\u3002", chartHeading: "\u30bf\u30a4\u30d4\u30f3\u30b0\u901f\u5ea6\u30c1\u30e3\u30fc\u30c8", chartIntro: "WPM\u306f\u826f\u3044\u76ee\u5b89\u3067\u3059\u304c\u3001\u6b63\u78ba\u7387\u3084\u30c6\u30b9\u30c8\u6761\u4ef6\u3068\u5408\u308f\u305b\u3066\u89e3\u91c8\u3059\u3079\u304d\u3067\u3059\u3002\u4f3c\u305f\u6761\u4ef6\u3067\u81ea\u5206\u306e\u7d50\u679c\u3092\u6bd4\u8f03\u3059\u308b\u3053\u3068\u3067\u3001\u672c\u5f53\u306e\u9032\u6b69\u3092\u78ba\u8a8d\u3067\u304d\u307e\u3059\u3002", tableLevel: "\u30ec\u30d9\u30eb", tableWpm: "WPM", tableMeaning: "\u610f\u5473", tableNext: "\u6b21\u306e\u76ee\u6a19" },
  ko: { metaHeading: "\ubb34\ub8cc \ud0c0\uc774\ud53c\ud551 \ud14c\uc2a4\ud2b8\ub7c0?", introA: "<strong>\ubb34\ub8cc \ud0c0\uc774\ud53c\ud551 \ud14c\uc2a4\ud2b8</strong>\ub294 \uc815\ud574\uc9c4 \uc2dc\uac04 \ub3d9\uc548 \ud654\ub9e9\uc5d0 \ud45c\uc2dc\ub41c \ud14d\uc2a4\ud2b8\ub97c \uc785\ub825\ud558\ub294 \ub3d9\uc548 \uc21c\uac04 \uc218\uc604\ub85c \uc18d\ub3c4\uc640 \uc815\ud655\ub3c4\ub97c \uc21c\uac04\uc801\uc73c\ub85c \uc218\uc604\ud569\ub2c8\ub2e4. \ud0c0\uc774\ud53c\ud551 \ud14c\uc2a4\ud2b8 \uc5fc\uc18c\ub294 \uac01 \uc2dc\ub3c4\uac00 \ub053\ub0a0 \ub550\ub9c8\ub2e4 WPM(\ubd84\ub09b \ub2e8\uc5b4 \uc218), \uc815\ud655\ub3c4, \uc624\ub958 \uc218\ub97c \uacc4\uc0b0\ud569\ub2c8\ub2e4.", introB: "\uacc4\uc815\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uace0\ub3c4 \uc5f0\uc2b5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub09c\uc774\ub3c4\uc640 \uc2dc\uac04\uc744 \uc120\ud0dd\ud558\uace0, \ud45c\uc2dc\ub41c \ud14d\uc2a4\ud2b8\ub97c \uc785\ub825\ud558\uc790\ub09e\ub9c8\uc790 \uacb0\uacfc\ub97c \uc989\uc2dc \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc628\ub7fc\uc778 \ud0c0\uc774\ud53c\ud551 \uc18d\ub3c4\ub97c \ubc60\ub9ac\uace0 \uc815\ud655\ud558\uac8c \uc218\uc604\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.", howHeading: "\uc628\ub7fc\uc778 \ud0c0\uc774\ud53c\ud551 \ud14c\uc2a4\ud2b8\uc758 \uc791\ub3d9 \ubc29\uc2dd\uacfc \uc0ac\uc6a9 \ub300\uc0c1", howA: "\uc26c\uc6c0, \ubcf4\ud1b5, \uc5b4\ub824\uc6c0 \uc911\uc5d0\uc11c \ub09c\uc774\ub3c4\ub97c \uc120\ud0dd\ud55c \ud6c4 1\ubd84, 2\ubd84, 3\ubd84, 5\ubd84 \uc911 \uc2dc\uac04\uc744 \uc120\ud0dd\ud558\uc138\uc694. \uc785\ub825\uc744 \uc2dc\uc791\ud558\ub294 \uc21c\uac04 \ud0c0\uc774\uba38\uac00 \uc790\ub3d9\uc73c\ub85c \uc2dc\uc791\ub418\uace0, \ucee4\uc11c\ub294 \ub2f9\uc2ec\uc774 \ud574\uc820\ub3c4 \ub3d9\uc548 \ud6c4 \ud604\uc7ac \uc704\uc9c0\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", howB: "\uc774 \ud0c0\uc774\ud53c\ud551 \ud14c\uc2a4\ud2b8\ub294 \ud559\uc0dd, \uc9c1\uc7a5\uc778, \ucd08\ubcf4\uc790 \ubc0f \ud0c0\uc774\ud53c\ud551 \uc18d\ub3c4\ub97c \uce21\uc815\ud558\uac70\ub098 \uac1c\uc120\ud558\uace0 \uc2f6\uc740 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uc720\uc6a9\ud569\ub2c8\ub2e4. \uc18d\ub3c4\ub97c \ub179\uc774\uae30 \uc804\uc5d0 \uc815\ud655\ub3c4\ub97c \uc801\uc65c\uc9c0\ub124\uae30 \uc704\ud574 \uc6d0\ud558\ub294 \ub9cc\ud07c \ud14c\uc2a4\ud2b8\ub97c \ubc18\ubb35\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub54c\ub610\ud55c \uc790\uc2e0\uc774 \uc6d0\ud558\ub294 \ud14d\uc2a4\ud2b8\ub97c \uc785\ub825\ud560 \uc218 \uc788\ub294 \ucee4\uc2a4\ud140 \ubaa8\ub4dc\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub354 \ubb34\ucda4\ud654\ub420 \ud14d\uc2a4\ud2b8 \uc5f0\uc2b5\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.", chartHeading: "\ud0c0\uc774\ud53c\ud551 \uc18d\ub3c4 \ucc28\ud2b8", chartIntro: "WPM\uc740 \uc88b\uc740 \uae30\uc900\uc810\uc774\uc9c0\ub9cc \uc815\ud655\ub3c4\uc640 \ud14c\uc2a4\ud2b8 \uc870\uac74\uacfc \ud568\uaee8 \ud574\uc11d\ud574\uc57c \ud569\ub2c8\ub2e4. \ubcf4\uc2a4\ud55c \uc870\uac74\uc5d0\uc11c \uc790\uc2e0\uc758 \uacb0\uacfc\ub97c \ube44\uad50\ud558\uc138\uc694.", tableLevel: "\uc218\uc900", tableWpm: "WPM", tableMeaning: "\uc758\ubbf8", tableNext: "\ub2e4\uc74c \ubaa9\ud45c" },
};

